"""The hybrid model of sections 4.4 and 4.5, on synthetic data generated by M1.

The recovery checks below are the point of the file: it is not enough that the
loss goes down, the learned D(S) has to land on the law that made the data,
-2.32(1 - S) and -0.19(1 - S). Everything is measured over the band of
supersaturations the training data actually covers, since outside it the paper
sees the same widening spread it reports in Figure 2(a).

The five experiment design is fixed and the data is noiseless, so the only thing
that changes between SEEDS is the network initialisation, as in the paper's 20
member ensembles. I ran 10 initialisations at these settings before fixing the
tolerances: the worst median relative error was 0.233 on D1 and 0.234 on D2,
against limits of 0.35 and 0.40, and the smallest Case A to Case B loss ratio was
5.2 against a limit of 3. One of those 10 gave a slightly non-monotonic D1(S),
so there is no monotonicity assertion here.
"""

import jax

jax.config.update("jax_enable_x64", True)

import jax.numpy as jnp
import pytest

from hybrid_pbe.data import make_dataset
from hybrid_pbe.grid import Grid, crystal_volume, mean_lengths
from hybrid_pbe.hybrid import LearnableSeed, NeuralDissolution
from hybrid_pbe.kinetics import M1, solubility
from hybrid_pbe.train import build_scalers, init_model, learned_rate_curve, train

GRID = Grid(n1=20, n2=10, L1_max=1000.0, L2_max=200.0)
SEEDS = (0, 1, 2)
STEPS = 350
LR = 1e-2
N_SUBSTEPS = 3
N_OBS = 7


def _make(seed):
    """One fixed dataset, one network initialisation per seed."""
    dataset = make_dataset(grid=GRID, kinetics=M1(), n_substeps=N_SUBSTEPS, n_obs=N_OBS)
    return dataset, build_scalers(dataset), jax.random.PRNGKey(1000 + seed)


def _observed_band(dataset, lo=10.0, hi=90.0):
    """The 10th to 90th percentile of the supersaturations seen in training."""
    S = jnp.concatenate([e.c_obs / solubility(e.T_values) for e in dataset.experiments])
    a, b = jnp.percentile(S, jnp.asarray([lo, hi]))
    return jnp.linspace(float(a), float(b), 9)


@pytest.fixture(scope="module")
def runs():
    """Train Case A and Case B once per seed and share them across the tests."""
    out = []
    for seed in SEEDS:
        dataset, scalers, k_model = _make(seed)
        trained = {}
        for case, assimilate in (("A", False), ("B", True)):
            model = init_model(k_model, dataset, width=16, depth=2)
            model, history = train(model, dataset, scalers, steps=STEPS, lr=LR,
                                   n_substeps=N_SUBSTEPS, assimilate_ic=assimilate)
            trained[case] = (model, history)
        out.append((seed, dataset, trained))
    return out


def test_neural_rate_is_negative_below_equilibrium_and_clipped_above():
    """Eq (15): negative softplus output, hard zero for S >= 1."""
    net = NeuralDissolution(jax.random.PRNGKey(0), s_mean=0.985, s_std=0.01,
                            t_mean=30.0, t_std=2.0,
                            ref_rate=jnp.asarray([0.05, 0.005]), width=8, depth=2)
    for S in (0.90, 0.975, 0.999):
        d = net.rates(jnp.asarray(S), jnp.asarray(30.0))
        assert float(d[0]) < 0.0 and float(d[1]) < 0.0
    for S in (1.0, 1.2):
        d = net.rates(jnp.asarray(S), jnp.asarray(30.0))
        assert float(d[0]) == 0.0 and float(d[1]) == 0.0


def test_neural_rate_is_size_independent_like_m1():
    net = NeuralDissolution(jax.random.PRNGKey(1), s_mean=0.985, s_std=0.01,
                            t_mean=30.0, t_std=2.0,
                            ref_rate=jnp.asarray([0.05, 0.005]), width=8, depth=2)
    a = net(jnp.asarray(50.0), jnp.asarray(10.0), jnp.asarray(0.98), jnp.asarray(30.0))
    b = net(jnp.asarray(900.0), jnp.asarray(190.0), jnp.asarray(0.98), jnp.asarray(30.0))
    assert float(a[0]) == pytest.approx(float(b[0]), rel=1e-14)
    assert float(a[1]) == pytest.approx(float(b[1]), rel=1e-14)


def test_learnable_seed_is_non_negative_and_holds_its_mass():
    """Section 2.2: assimilation adjusts the shape, the mass is renormalised."""
    key = jax.random.PRNGKey(4)
    raw = jax.random.normal(key, GRID.shape) * 1e6  # deliberately half negative
    seed = LearnableSeed(raw, GRID, target_volume=7.5e11)
    f0 = seed()
    assert float(jnp.min(f0)) >= 0.0
    assert float(crystal_volume(f0, GRID)) == pytest.approx(7.5e11, rel=1e-9)
    # A large perturbation changes the shape but not the mass.
    moved = LearnableSeed(raw + 3e6, GRID, target_volume=7.5e11)()
    assert float(crystal_volume(moved, GRID)) == pytest.approx(7.5e11, rel=1e-9)
    assert float(jnp.max(jnp.abs(moved - f0))) > 0.0


def test_training_reduces_the_trajectory_loss(runs):
    for seed, _, trained in runs:
        for case in ("A", "B"):
            history = trained[case][1]
            assert float(history[-1]) < 0.2 * float(history[0]), (seed, case)


def test_hybrid_recovers_the_m1_rate_law(runs):
    """Case B on data made by M1 has to reproduce eqs (9) and (10) over the
    supersaturations the data covers, not merely fit the trajectories."""
    for seed, dataset, trained in runs:
        model = trained["B"][0]
        S = _observed_band(dataset)
        d1, d2 = learned_rate_curve(model, S, 28.0)
        true1, true2 = M1().rates(S)
        err1 = jnp.median(jnp.abs(d1 - true1) / jnp.abs(true1))
        err2 = jnp.median(jnp.abs(d2 - true2) / jnp.abs(true2))
        assert float(err1) < 0.35, (seed, float(err1))
        assert float(err2) < 0.40, (seed, float(err2))
        # Dissolution, so both rates are negative across the band.
        assert bool(jnp.all(d1 < 0.0)) and bool(jnp.all(d2 < 0.0)), seed
        # And the two dimensions keep roughly the published 2.32 / 0.19 ratio.
        ratio = jnp.median(d1 / d2)
        assert 0.7 < float(ratio) / (2.32 / 0.19) < 1.8, (seed, float(ratio))


def test_assimilating_initial_conditions_beats_holding_them_fixed(runs):
    """Section 2.2 in miniature. The measured seed here is 6 percent too long in
    L1. Held fixed (Case A) the network absorbs the mismatch into the rate law
    and lands 40 to 90 percent off M1; freed (Case B) the loss drops by at least
    a factor of five on all 10 initialisations I tried and the recovered rate
    lands within about 23 percent."""
    improvements, errors_a, errors_b = [], [], []
    for seed, dataset, trained in runs:
        loss_a = float(trained["A"][1][-1])
        loss_b = float(trained["B"][1][-1])
        improvements.append(loss_a / loss_b)
        S = _observed_band(dataset)
        true1, _ = M1().rates(S)
        for case, bucket in (("A", errors_a), ("B", errors_b)):
            d1, _ = learned_rate_curve(trained[case][0], S, 28.0)
            bucket.append(float(jnp.median(jnp.abs(d1 - true1) / jnp.abs(true1))))
    assert min(improvements) > 3.0, improvements
    assert sorted(errors_b)[1] < sorted(errors_a)[1], (errors_a, errors_b)


def test_assimilation_moves_the_seed_toward_the_true_initial_condition(runs):
    """The calibrated f0 should sit between the measured seed and the truth in
    mean length, the shift the paper reports as 24.1 um for E7."""
    closer = 0
    for seed, dataset, trained in runs:
        model = trained["B"][0]
        for i, e in enumerate(dataset.experiments):
            true_L1 = float(mean_lengths(e.f0_true, GRID)[0])
            meas_L1 = float(mean_lengths(e.f0_measured, GRID)[0])
            fit_L1 = float(mean_lengths(model.seeds[i](), GRID)[0])
            if abs(fit_L1 - true_L1) < abs(meas_L1 - true_L1):
                closer += 1
    total = sum(len(d.experiments) for _, d, _ in runs)
    assert closer == total, (closer, total)


def test_assimilated_seeds_stay_physical(runs):
    """ReLU plus renormalisation, so every calibrated f0 is non-negative and
    carries the measured seed mass."""
    for seed, dataset, trained in runs:
        model = trained["B"][0]
        for i in range(len(dataset.experiments)):
            f0 = model.seeds[i]()
            assert float(jnp.min(f0)) >= 0.0
            assert float(crystal_volume(f0, GRID)) == pytest.approx(
                dataset.seed_volume, rel=1e-8)
